    # rule step (hop/world.slg:53)
    # @why one tick of play: carry, steer, jump, fall, then everything the hero touches
    def self.step(pad)
      Spec.rule do
        Spec.guard("Over") { mode == Hop::Model::Mode::Playing }
        t = ticks + 1
        self.ticks = t
        was = player
        tops = stage.movers.map { |m| Hop::Physics::Placed.new(no: m.no, box: Hop::Physics.mover_box(m, t)) }
        at = was.at
        if was.riding.is_a?(Spec::Some)
          ridden = stage.movers.select { |m| was.riding == Spec::Some.new(m.no) }
          ridden.each do |m|
            at = Hop::Geom.plus(at, Hop::Physics.mover_shift(m, t))
          end
        end
        target = Hop::Physics.walk_target(pad)
        accel = was.grounded ? Hop::Physics.ground_accel : Hop::Physics.air_accel
        vy = was.vel.y
        coyote = was.coyote
        if pad.jump && !was.jump_held && (was.grounded || was.coyote > 0)
          vy = Hop::Physics.jump_speed
          coyote = 0
          Spec.effect("cli.out", :line, "#{t} jump")
        elsif !pad.jump && vy > Hop::Physics.hop_cut
          vy = Hop::Physics.hop_cut
        end
        vy = [vy - Hop::Physics.gravity, 0 - Hop::Physics.max_fall].max
        sx = Hop::Physics.slide_x(at, Hop::Geom.approach(was.vel.x, target.x, accel), stage.solids)
        at = at.with(x: sx.pos)
        sz = Hop::Physics.slide_z(at, Hop::Geom.approach(was.vel.z, target.z, accel), stage.solids)
        at = at.with(z: sz.pos)
        f = Hop::Physics.fall(at, vy, stage.solids, tops)
        at = at.with(y: f.y)
        if f.grounded && !was.grounded
          Spec.effect("cli.out", :line, "#{t} land")
        end
        self.player = Hop::Model::Player.new(
          at:,
          vel: Hop::Geom::Vec3.new(x: sx.vel, y: f.vel, z: sz.vel),
          grounded: f.grounded,
          coyote: f.grounded ? Hop::Physics.coyote_ticks : [coyote - 1, 0].max,
          jump_held: pad.jump,
          riding: f.riding,
          yaw: Hop::Physics.facing(pad, was.yaw)
        )
        crawlers.values.each do |c|
          value = Hop::Physics.patrol(c)
          self.crawlers = Spec::Maps.put(crawlers, c.no, value)
        end
        stage.gems.each do |g|
          if !taken.include?(g.no) &&
            Hop::Geom.touches(Hop::Physics.body(at), Hop::Geom.around_centre(g.at, Hop::Physics.gem_half))
            self.taken = Spec::Sets.add(taken, g.no)
            Spec.effect("cli.out", :line, "#{t} gem #{g.no}")
          end
        end
        alive = true
        crawlers.values.each do |c|
          if alive && Hop::Geom.touches(Hop::Physics.body(at), Hop::Physics.crawler_box(c))
            if Hop::Physics.stomps(at.y, vy, c)
              self.crawlers = crawlers.except(c.no)
              self.player = player.with(vel: player.vel.with(y: Hop::Physics.stomp_bounce), grounded: false, riding: Spec::NONE)
              Spec.effect("cli.out", :line, "#{t} stomp #{c.no}")
            else
              lose("hit")
              alive = false
            end
          end
        end
        if alive && at.y < Hop::Physics.kill_y
          lose("fall")
          alive = false
        end
        goal = Hop::Geom.around_feet(stage.goal, Hop::Physics.goal_half)
        if alive && Hop::Geom.touches(Hop::Physics.body(at), goal)
          self.mode = Hop::Model::Mode::Won
          Spec.effect("cli.out", :line, "#{t} won")
        end
        nil
      end
    end

